#[derive(Serialize)]
pub struct Eta {
    minutes: u32,
    driver_id: String,
}

pub async fn get_eta(
    State(app): State<Arc<AppState>>,
    Path(ride_id): Path<String>,
) -> Result<Json<Eta>, StatusCode> {
    let ride = app
        .rides
        .get(&ride_id)
        .await
        .map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?
        .ok_or(StatusCode::NOT_FOUND)?;

    let minutes = app.routing.estimate(&ride.pickup, &ride.driver_position).await;
    Ok(Json(Eta { minutes, driver_id: ride.driver_id }))
}

