@Service
public class SlotBookingService {

    private static final Logger log = LoggerFactory.getLogger(SlotBookingService.class);

    private final SlotRepository slots;
    private final ApplicationEventPublisher events;

    public SlotBookingService(SlotRepository slots, ApplicationEventPublisher events) {
        this.slots = slots;
        this.events = events;
    }

    @Transactional
    public Appointment book(UUID slotId, UUID patientId) {
        Slot slot = slots.findByIdForUpdate(slotId)
                .orElseThrow(() -> new SlotNotFoundException(slotId));
        if (slot.isTaken()) {
            throw new SlotAlreadyTakenException(slotId);
        }
        Appointment appointment = slot.reserveFor(patientId);
        log.info("Slot {} reserved for patient {}", slotId, patientId);
        events.publishEvent(new AppointmentBooked(appointment.getId()));
        return appointment;
    }
}

const { Worker } = require('bullmq');
const { transcode } = require('./ffmpeg');
const logger = require('./logger');

const worker = new Worker(
  'transcode',
  async (job) => {
    const { assetId, source, ladder } = job.data;
    logger.info({ assetId }, 'starting transcode');
    for (const rung of ladder) {
      await job.updateProgress({ rung: rung.height });
      await transcode(source, rung);
    }
    return { assetId, renditions: ladder.length };
  },
  { connection: { host: process.env.REDIS_HOST }, concurrency: 2 }
);

worker.on('failed', (job, err) => {
  logger.error({ assetId: job.data.assetId, err }, 'transcode failed');
});

module.exports = worker;

data class FareQuote(val baseCents: Long, val perKmCents: Long, val surge: Double)

class FareCalculator(private val rates: RateTable) {

    fun quote(distanceKm: Double, zone: Zone): FareQuote {
        val rate = rates.forZone(zone) ?: error("no rate for ${zone.id}")
        return FareQuote(
            baseCents = rate.base,
            perKmCents = (rate.perKm * distanceKm).toLong(),
            surge = if (zone.demandRatio > 1.5) minOf(zone.demandRatio, 3.0) else 1.0,
        )
    }
}

suspend fun estimate(rideId: String, calculator: FareCalculator, repo: RideRepository): FareQuote {
    val ride = repo.find(rideId) ?: throw NotFoundException("ride $rideId")
    return calculator.quote(ride.distanceKm, ride.pickupZone)
}

