public sealed class CardTestingRule : IFraudRule
{
    private readonly IAttemptStore _attempts;
    private readonly ILogger<CardTestingRule> _logger;

    public CardTestingRule(IAttemptStore attempts, ILogger<CardTestingRule> logger)
    {
        _attempts = attempts;
        _logger = logger;
    }

    public async Task<RuleResult> EvaluateAsync(PaymentAttempt attempt, CancellationToken ct)
    {
        var recent = await _attempts.CountDeclinedAsync(attempt.CardFingerprint, TimeSpan.FromMinutes(15), ct);
        if (recent >= 5)
        {
            _logger.LogWarning("Card {Fingerprint} declined {Count} times in 15 minutes", attempt.CardFingerprint, recent);
            return RuleResult.Block("card_testing");
        }

        return RuleResult.Pass();
    }
}

int read_temperature(int fd, float *celsius)
{
    uint8_t raw[2];
    if (read(fd, raw, sizeof raw) != sizeof raw)
        return -1;
    *celsius = ((raw[0] << 8) | raw[1]) * 0.0625f;
    return 0;
}

