#include <chrono>
#include <mutex>
#include <optional>
#include <unordered_map>

class SessionCache {
public:
    explicit SessionCache(std::chrono::seconds ttl) : ttl_(ttl) {}

    std::optional<Session> get(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = entries_.find(id);
        if (it == entries_.end() || it->second.expires < std::chrono::steady_clock::now()) {
            return std::nullopt;
        }
        return it->second.session;
    }

    void put(const std::string& id, Session session) {
        std::lock_guard<std::mutex> lock(mutex_);
        entries_[id] = {std::move(session), std::chrono::steady_clock::now() + ttl_};
    }

private:
    struct Entry { Session session; std::chrono::steady_clock::time_point expires; };
    std::chrono::seconds ttl_;
    std::mutex mutex_;
    std::unordered_map<std::string, Entry> entries_;
};

