import (
	"context"
	"errors"
	"time"
)

var ErrBlocked = errors.New("transaction blocked")

type Checker struct {
	store  VelocityStore
	limits Limits
}

func (c *Checker) Check(ctx context.Context, tx Transaction) error {
	ctx, cancel := context.WithTimeout(ctx, 200*time.Millisecond)
	defer cancel()

	n, err := c.store.CountSince(ctx, tx.AccountID, time.Now().Add(-10*time.Minute))
	if err != nil {
		return err
	}
	if n >= c.limits.MaxPer10Min {
		return ErrBlocked
	}
	return nil
}
